  + 'export type TabsTabProps = ComponentProps<"button"> & {\n'
  + '  value: string;\n'
  + '};\n'
  + '\n'
  + 'const TabsTab: FC<TabsTabProps> = (props) => {\n'
  + '  const { variant, size } = useTabsContext();\n'
  + '\n'
  + '  if (variant === "default") {\n'
  + '    return <TabsTabDefault {...props} size={size} />;\n'
  + '  } else if (variant === "enclosed") {\n'
  + '    return <TabsTabEnclosed {...props} size={size} />;\n'
  + '  } else {\n'
  + '    throw new Error(`Unknown Tabs variant: ${variant}`);\n'
  + '  }\n'
  + '};\n'
  + '\n'
  + 'TabsTab.displayName = "Tabs.Tab";\n'
  + '\n'
  + 'export { TabsTab };\n'
